-- Reuse the existing lifecycle insert and its (user, type, market) unique index.
-- Settlement events are generated by the engine, so client calls cannot reserve
-- their deduplication keys or supply their outcomes and wallet amounts.
ALTER FUNCTION public.create_market_notification(uuid, text, text, text, uuid, jsonb)
    SET SCHEMA private;
REVOKE ALL ON FUNCTION private.create_market_notification(uuid, text, text, text, uuid, jsonb)
    FROM PUBLIC, anon, authenticated, service_role;

CREATE FUNCTION public.create_market_notification(
    p_user_id uuid,
    p_type text,
    p_title text,
    p_body text,
    p_market_id uuid,
    p_metadata jsonb DEFAULT '{}'::jsonb
) RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER SET search_path = public, pg_temp
AS $$
BEGIN
    IF p_type IN ('market_resolved', 'payout_received') THEN
        RAISE EXCEPTION 'Settlement notifications are generated by market settlement';
    END IF;

    RETURN private.create_market_notification(p_user_id, p_type, p_title, p_body, p_market_id, p_metadata);
END;
$$;

REVOKE ALL ON FUNCTION public.create_market_notification(uuid, text, text, text, uuid, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_market_notification(uuid, text, text, text, uuid, jsonb)
    TO anon, authenticated, service_role;

CREATE FUNCTION private.notify_market_settlement(
    p_user_id uuid,
    p_market_id uuid,
    p_market_title text,
    p_outcome text,
    p_amount numeric DEFAULT NULL,
    p_is_refund boolean DEFAULT false
) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp
AS $$
DECLARE
    v_type text := 'market_resolved';
    v_title text := 'Market Resolved';
    v_body text := format('Outcome: %s. "%s" has resolved.', p_outcome, p_market_title);
    v_metadata jsonb := jsonb_build_object('outcome', p_outcome);
BEGIN
    IF p_amount IS NOT NULL THEN
        v_type := 'payout_received';
        v_title := CASE WHEN p_is_refund THEN 'Stake Refunded' ELSE 'Payout Received' END;
        v_body := format('%s Tartan Coins %s for "%s".',
            trim_scale(p_amount), CASE WHEN p_is_refund THEN 'refunded' ELSE 'paid' END, p_market_title);
        v_metadata := v_metadata || jsonb_build_object('amount', p_amount, 'is_refund', p_is_refund);
    END IF;

    PERFORM private.create_market_notification(p_user_id, v_type, v_title, v_body, p_market_id, v_metadata);
EXCEPTION WHEN OTHERS THEN
    -- A delivery failure rolls back only this notification attempt.
    RAISE WARNING 'Could not create % notification (SQLSTATE %)', v_type, SQLSTATE;
END;
$$;

CREATE FUNCTION private.notify_market_resolved(
    p_market_id uuid, p_market_title text, p_creator_id uuid, p_outcome text
) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp
AS $$
DECLARE
    v_user_id uuid;
BEGIN
    FOR v_user_id IN
        SELECT p_creator_id
        UNION SELECT user_id FROM bets WHERE market_id = p_market_id
        UNION SELECT voter_id FROM community_votes WHERE market_id = p_market_id
        UNION SELECT submitter_id FROM dispute_submissions WHERE market_id = p_market_id
        UNION SELECT vote.voter_id
              FROM resolution_votes AS vote JOIN disputes AS dispute ON dispute.id = vote.dispute_id
              WHERE dispute.market_id = p_market_id
        ORDER BY 1
    LOOP
        PERFORM private.notify_market_settlement(v_user_id, p_market_id, p_market_title, p_outcome);
    END LOOP;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Could not deliver market resolution notifications (SQLSTATE %)', SQLSTATE;
END;
$$;

REVOKE ALL ON FUNCTION private.notify_market_settlement(uuid, uuid, text, text, numeric, boolean)
    FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION private.notify_market_resolved(uuid, text, uuid, text)
    FROM PUBLIC, anon, authenticated, service_role;

-- Community retries return before any credits or notifications. Creator and
-- dispute settlements keep the existing status checks and market lock.
CREATE OR REPLACE FUNCTION private.settle_binary_market(
    p_market_id UUID,
    p_outcome   TEXT
) RETURNS JSONB AS $$
DECLARE
    v_status TEXT;
    v_market markets%ROWTYPE;
    v_yes integer;
    v_no integer;
    v_community boolean;
    v_yes_pool     NUMERIC;
    v_no_pool      NUMERIC;
    v_total_pool   NUMERIC;
    v_winning_pool NUMERIC;
    v_credit       RECORD;
BEGIN
    IF p_outcome NOT IN ('YES', 'NO') THEN
        RAISE EXCEPTION 'Invalid outcome: must be YES or NO';
    END IF;

    SELECT status, yes_pool_total, no_pool_total
    INTO v_status, v_yes_pool, v_no_pool
    FROM markets WHERE id = p_market_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Market not found';
    END IF;

    SELECT * INTO v_market FROM markets WHERE id=p_market_id;
    IF v_status='resolved' AND EXISTS (SELECT 1 FROM private.community_settlements WHERE market_id=p_market_id AND outcome=p_outcome AND rewards_paid) THEN
        RETURN jsonb_build_object('market_id',p_market_id,'status','resolved','outcome',p_outcome);
    END IF;
    v_community := v_status='pending_resolution' AND v_market.proposed_outcome IS NULL;
    IF v_community THEN
        IF v_market.market_type <> 'binary' OR v_market.resolution_window_end IS NULL OR clock_timestamp() < v_market.resolution_window_end THEN
            RAISE EXCEPTION 'Community resolution window has not ended or market is not binary';
        END IF;
        SELECT count(*) FILTER (WHERE selected_outcome='YES'), count(*) FILTER (WHERE selected_outcome='NO')
        INTO v_yes,v_no FROM community_votes WHERE market_id=p_market_id;
        IF v_yes+v_no < 3 OR v_yes=v_no OR p_outcome <> (CASE WHEN v_yes>v_no THEN 'YES' ELSE 'NO' END) THEN
            RAISE EXCEPTION 'Community quorum and majority must match outcome';
        END IF;
        INSERT INTO private.community_settlements (market_id,outcome) VALUES (p_market_id,p_outcome);
    END IF;
    -- Deterministic profile lock order across payouts and voter rewards.
    PERFORM 1 FROM profiles WHERE id IN (
        SELECT user_id FROM bets WHERE market_id=p_market_id
        UNION SELECT voter_id FROM community_votes WHERE market_id=p_market_id
    ) ORDER BY id FOR UPDATE;
    IF v_status NOT IN ('pending_resolution', 'disputed', 'admin_review') THEN
        RAISE EXCEPTION 'Market cannot be finalized from status: %', v_status;
    END IF;

    UPDATE markets SET
        status           = 'resolved',
        resolved_outcome = p_outcome,
        resolved_at      = now()
    WHERE id = p_market_id;

    v_total_pool := v_yes_pool + v_no_pool;

    IF p_outcome = 'YES' THEN
        v_winning_pool := v_yes_pool;
    ELSE
        v_winning_pool := v_no_pool;
    END IF;

    -- Keep one ledger entry per stake when refunding and one per winner otherwise.
    -- Aggregate just the credits posted by this settlement for wallet and delivery.
    FOR v_credit IN
        WITH credits AS (
            SELECT user_id, amount FROM bets
            WHERE market_id = p_market_id AND v_winning_pool = 0
            UNION ALL
            SELECT user_id, trunc(sum(amount) * (v_total_pool / nullif(v_winning_pool, 0)), 2)
            FROM bets
            WHERE market_id = p_market_id AND v_winning_pool <> 0 AND side = p_outcome
            GROUP BY user_id
        ), posted AS (
            INSERT INTO transactions (user_id, market_id, transaction_type, amount)
            SELECT user_id, p_market_id, 'payout', amount FROM credits
            RETURNING user_id, amount
        )
        SELECT user_id, sum(amount) AS amount FROM posted GROUP BY user_id ORDER BY user_id
    LOOP
        UPDATE profiles SET tartan_coin_balance = tartan_coin_balance + v_credit.amount
        WHERE id = v_credit.user_id;

        IF v_credit.amount > 0 THEN
            PERFORM private.notify_market_settlement(
                v_credit.user_id, p_market_id, v_market.title, p_outcome,
                v_credit.amount, v_winning_pool = 0
            );
        END IF;
    END LOOP;

    IF v_community THEN PERFORM distribute_voter_rewards(p_market_id,p_outcome); END IF;
    PERFORM private.notify_market_resolved(p_market_id, v_market.title, v_market.creator_id, p_outcome);

    RETURN jsonb_build_object(
        'market_id', p_market_id,
        'status', 'resolved',
        'outcome', p_outcome
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp;

CREATE OR REPLACE FUNCTION public.admin_resolve_market(
    p_market_id UUID,
    p_outcome   TEXT,
    p_admin_id  UUID
) RETURNS JSONB AS $$
DECLARE
    v_claims       JSONB := nullif(current_setting('request.jwt.claims', true), '')::jsonb;
    v_market       markets%ROWTYPE;
    v_refund       RECORD;
    v_refunded     NUMERIC := 0;
    v_refund_users INTEGER := 0;
    v_result       JSONB;
BEGIN
    IF p_outcome IS NULL OR p_outcome NOT IN ('YES', 'NO', 'AMBIGUOUS') THEN
        RAISE EXCEPTION 'Invalid outcome: must be YES, NO or AMBIGUOUS';
    END IF;

    -- API calls carry the acting admin's JWT; a client cannot name another admin.
    IF v_claims IS NOT NULL
       AND coalesce(v_claims ->> 'role', '') <> 'service_role'
       AND (v_claims ->> 'sub') IS DISTINCT FROM p_admin_id::text THEN
        RAISE EXCEPTION 'Only admins can resolve markets in admin review';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM profiles WHERE id = p_admin_id AND role IN ('admin', 'super_admin')
    ) THEN
        RAISE EXCEPTION 'Only admins can resolve markets in admin review';
    END IF;

    -- Market lock first (as betting/backroll do); waiters re-read the committed status.
    SELECT * INTO v_market FROM markets WHERE id = p_market_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Market not found';
    END IF;
    IF v_market.status = 'resolved' THEN
        RAISE EXCEPTION 'Market is already resolved';
    END IF;
    IF v_market.status <> 'admin_review' THEN
        RAISE EXCEPTION 'Market is not in admin_review status';
    END IF;
    IF v_market.creator_id = p_admin_id THEN
        RAISE EXCEPTION 'Market creators cannot resolve their own markets';
    END IF;

    UPDATE disputes SET resolved_by_admin = TRUE WHERE market_id = p_market_id;

    IF p_outcome = 'AMBIGUOUS' THEN
        -- Refund every stake (binary or option) once; pools stay as historical totals.
        PERFORM 1 FROM profiles
        WHERE id IN (SELECT user_id FROM bets WHERE market_id = p_market_id)
        ORDER BY id FOR UPDATE;

        UPDATE markets SET
            status           = 'resolved',
            resolved_outcome = 'AMBIGUOUS',
            resolved_at      = now()
        WHERE id = p_market_id;

        FOR v_refund IN
            SELECT user_id, SUM(amount) AS total
            FROM bets WHERE market_id = p_market_id
            GROUP BY user_id ORDER BY user_id
        LOOP
            UPDATE profiles SET tartan_coin_balance = tartan_coin_balance + v_refund.total
            WHERE id = v_refund.user_id;

            INSERT INTO transactions (user_id, market_id, transaction_type, amount)
            VALUES (v_refund.user_id, p_market_id, 'refund', v_refund.total);

            IF v_refund.total > 0 THEN
                PERFORM private.notify_market_settlement(
                    v_refund.user_id, p_market_id, v_market.title, p_outcome, v_refund.total, true
                );
            END IF;

            v_refunded := v_refunded + v_refund.total;
            v_refund_users := v_refund_users + 1;
        END LOOP;

        PERFORM private.notify_market_resolved(p_market_id, v_market.title, v_market.creator_id, p_outcome);

        RETURN jsonb_build_object(
            'market_id', p_market_id,
            'status', 'resolved',
            'outcome', 'AMBIGUOUS',
            'refunded_total', v_refunded,
            'refunded_users', v_refund_users
        );
    END IF;

    IF v_market.market_type <> 'binary' THEN
        RAISE EXCEPTION 'YES/NO admin resolution requires a binary market';
    END IF;

    PERFORM set_config('pheme.admin_resolution', p_market_id::text, true);
    v_result := finalize_resolution(p_market_id, p_outcome);
    PERFORM set_config('pheme.admin_resolution', '', true);
    RETURN v_result;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp;
